/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    if (!event.payload.action) return;
    if (event.payload.action === "start") {
        return {
            event: 'Notify Conference Bridge Initiate',
            value: {
                'Source': 'Notify Conference Dialog'
            }
        };
    }
}
